INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7701, '2 Samuel 8:5', '2 Samuel', 8, 5, '&nbsp;کله چې د دمشق شاميانو د هدد‌عزر بادشاه مدد دپاره يو لښکر ولېږلو، نو داؤد په هغوئ باندې حمله وکړه او دوويشت زره سړى يې ترې نه ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7702, '2 Samuel 8:6', '2 Samuel', 8, 6, '&nbsp;بيا هغۀ په هغه علاقه کښې فوجى کېمپونه ولګول او هغوئ د هغۀ د اختيار لاندې راغلل او محصُول يې ورکولو. مالِک خُدائ په هر ځائ کښې داؤد له فتح ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7703, '2 Samuel 8:7', '2 Samuel', 8, 7, '&nbsp;داؤد د هدد‌عزر د آفسرانو د سرو زرو ډالونه قبضه کړل او دا يې يروشلم ته راوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7704, '2 Samuel 8:8', '2 Samuel', 8, 8, '&nbsp;هغۀ د بطاه او بيروتى ښارونو نه په لوئ مِقدار کښې زېړ هم يوړل چې په دې ښارونو باندې هدد‌عزر حکومت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7705, '2 Samuel 8:9', '2 Samuel', 8, 9, '&nbsp;د حمات بادشاه توعى خبر شو چې داؤد د هدد‌عزر ټول لښکر له شکست ورکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7706, '2 Samuel 8:10', '2 Samuel', 8, 10, '&nbsp;نو هغۀ خپل زوئ يورام بادشاه داؤد له ولېږلو او په هدد‌عزر باندې د فتحې مبارکى يې ورکړه، چې د هغۀ خِلاف توعى څو ځلې جنګ کړے وو. يورام داؤد له تُحفې يوړې چې د سرو زرو، سپينو زرو او زېړو نه جوړې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7707, '2 Samuel 8:11', '2 Samuel', 8, 11, '&nbsp;داؤد بادشاه دا تُحفې وقف کړې چې په عبادت کښې به استعماليږى، په دې کښې هغه سرۀ او سپين زر هم شامل وُو چې د هغه قومونو نه يې اخستى وُو چې کوم يې فتح کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7708, '2 Samuel 8:12', '2 Samuel', 8, 12, '&nbsp;د ادوم، موآب، عمون، فلستيه او عماليق قومونو نه، هم داسې د هغه مالِ غنيمت حِصه هم چې هغۀ د هدد‌عزر نه اخستے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7709, '2 Samuel 8:13', '2 Samuel', 8, 13, '&nbsp;کله چې داؤد د مالګې په وادۍ کښې اتلس زره ادوميانو وژلو نه پس راوګرځېدو نو هغه نور هم مشهور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7710, '2 Samuel 8:14', '2 Samuel', 8, 14, '&nbsp;هغۀ په ټول ادوم کښې فوجى کېمپونه ولګول او د هغه ځائ خلق د هغۀ د اختيار لاندې راغلل. مالِک خُدائ داؤد له په هر ځائ کښې فتح ورکوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7711, '2 Samuel 8:15', '2 Samuel', 8, 15, '&nbsp;داؤد په ټولو بنى اِسرائيلو باندې حکومت کولو او هغۀ دا خبره يقينى کړه چې د هغۀ د ټولو خلقو سره همېشه د عدل او اِنصاف سلوک کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7712, '2 Samuel 8:16', '2 Samuel', 8, 16, '&nbsp;يوآب د لښکر مشر وو چې د هغۀ مور ضروياه وه، د اخيلود زوئ يهوسفط منشى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7713, '2 Samuel 8:17', '2 Samuel', 8, 17, '&nbsp;د اخيطوب زوئ صدوق او د ابياتار زوئ اخيمُلک اِمامان وُو، شراياه د عدالت منشى وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7714, '2 Samuel 8:18', '2 Samuel', 8, 18, '&nbsp;د يهويدع زوئ بناياه د داؤد د محافظانو مشر وو او د داؤد زامن اِمامان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7715, '2 Samuel 9:1', '2 Samuel', 9, 1, '&nbsp;يوه ورځ داؤد تپوس وکړو، ”د ساؤل د خاندان څوک پاتې دى؟ کۀ څوک وى نو د يونتن د خاطره به زۀ پرې مهربان شم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7716, '2 Samuel 9:2', '2 Samuel', 9, 2, '&nbsp;د ساؤل د خاندان يو نوکر راوغوښتے شو چې نوم يې ضيبا وو. بادشاه ترې نه تپوس وکړو، ”تۀ ضيبا يې څۀ؟“ هغۀ جواب ورکړو، ”ستا خِدمت کوونکے حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7717, '2 Samuel 9:3', '2 Samuel', 9, 3, '&nbsp;بادشاه ترې نه تپوس وکړو، ”د ساؤل په خاندان کښې داسې څوک پاتې دے څۀ چې هغۀ ته وفادارى او مِهربانى وښايم، لکه څنګه چې ما د خُدائ پاک سره وعده کړې ده؟“ ضيبا جواب ورکړو، ”د يونتن يو زوئ تر اوسه پورې شته او هغه په دواړو پښو ګوډ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7718, '2 Samuel 9:4', '2 Samuel', 9, 4, '&nbsp;بادشاه تپوس وکړو، ”هغه چرته دے؟“ ضيبا ورته ووئيل، ”هغه په لودبار کښې د عمى‌اېل زوئ مکير په کور کښې دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7719, '2 Samuel 9:5', '2 Samuel', 9, 5, '&nbsp;نو داؤد بادشاه هغه راوغوښتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7720, '2 Samuel 9:6', '2 Samuel', 9, 6, '&nbsp;کله چې د ساؤل نمسے او د يونتن زوئ مفيبوست راورسېدو، هغه داؤد ته د عزت نه ټيټ شو. داؤد وفرمائيل، ”مفيبوسته.“ او هغۀ ورته ووئيل، ”ستا خِدمتګار حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7721, '2 Samuel 9:7', '2 Samuel', 9, 7, '&nbsp;داؤد جواب ورکړو، ”يرېږه مه، ستا د پلار په وجه زۀ په تا مِهربانه يم. زۀ به تا له هغه ټوله زمکه واپس درکړم کومه چې ستا د نيکۀ ساؤل وه او تا ته به زما په دسترخوان باندې همېشه هرکلے وئيلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7722, '2 Samuel 9:8', '2 Samuel', 9, 8, '&nbsp;مفيبوست يو ځل بيا ټيټ شو او وې وئيل، ”صاحِبه، زما نه خو يو مړ سپے هم ښۀ دے، تۀ زما سره ولې دومره ښۀ يې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7723, '2 Samuel 9:9', '2 Samuel', 9, 9, '&nbsp;بيا بادشاه د ساؤل نوکر ضيبا راوغوښتو او ورته يې وفرمائيل، ”زۀ ستا د نېک نمسى، مفيبوست له هغه هر څۀ ورکوم چې هغه د ساؤل او د هغۀ د خاندان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7724, '2 Samuel 9:10', '2 Samuel', 9, 10, '&nbsp;تۀ، ستا زامن او ستا نوکران به د ساؤل د خاندان زمکه کَرى او فصل به يې راوړى چې هغوئ ته خوراک ملاويږى. خو مفيبوست به همېشه زما په دسترخوان باندې مېلمه وى.“ د ضيبا پينځلس زامن او شل نوکران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7725, '2 Samuel 9:11', '2 Samuel', 9, 11, '&nbsp;ضيبا ورته ووئيل، ”بادشاه سلامت، زۀ به هر هغه څۀ کوم چې تۀ يې حُکم کوې.“ مفيبوست د بادشاه په دسترخوان باندې د بادشاه د زوئ په شان خوراک کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7726, '2 Samuel 9:12', '2 Samuel', 9, 12, '&nbsp;د مفيبوست يو زلمے زوئ وو چې نوم يې ميکا وو. د ضيبا د خاندان مکمل کسان د مفيبوست نوکران شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7727, '2 Samuel 9:13', '2 Samuel', 9, 13, '&nbsp;نو مفيبوست چې په دواړو پښو شل وو هغه په يروشلم کښې اوسېدو، هغۀ به همېشه د بادشاه په دسترخوان خوراک کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7728, '2 Samuel 10:1', '2 Samuel', 10, 1, '&nbsp;څۀ موده وروستو د عمون بادشاه ناحس مړ شو او د هغۀ زوئ حنون بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7729, '2 Samuel 10:2', '2 Samuel', 10, 2, '&nbsp;داؤد بادشاه وفرمائيل، ”زۀ به په حنون هغسې مِهربانه شم، لکه چې د هغۀ پلار ناحس په ما مِهربانه وو.“ نو داؤد پېغام وړُونکى ورولېږل چې هغۀ له تسلى ورکړى. کله چې هغوئ عمون ته ورسېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7730, '2 Samuel 10:3', '2 Samuel', 10, 3, '&nbsp;د عمونيانو مشرانو بادشاه ته ووئيل، ”ستا خيال دا دے څۀ چې داؤد ستا د پلار درناوے کوى چې هغۀ دا کسان د همدردۍ دپاره درلېږلى دى؟ بلکل نه، هغۀ دا د جاسوسۍ دپاره رالېږلى دى چې ښار ولټوى او په مونږ باندې فتح حاصله کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7731, '2 Samuel 10:4', '2 Samuel', 10, 4, '&nbsp;حنون د داؤد پېغام وړُونکى ونيول او يو طرف ته ږيرې يې ورله وخرئيلې، جامې يې ورله وشلولې چې د نوم نه لاندې بربنډ شى او هغوئ يې واپس ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7732, '2 Samuel 10:5', '2 Samuel', 10, 5, '&nbsp;هغوئ چې کورونو ته راواپس شول نو ډېر زيات شرمېدل. کله چې داؤد خبر شو چې څۀ شوى وُو، نو هغۀ خبر ورولېږلو چې هغوئ دې تر هغې پورې په يريحو کښې ايسار شى چې ږيرې يې بيا راوخېژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7733, '2 Samuel 10:6', '2 Samuel', 10, 6, '&nbsp;کله چې عمونيانو ته پته ولګېده چې داؤد يې دشمن شوے دے، نو هغوئ د بيت‌رِحوب او ضوباه نه شل زره شامى فوجيان په پېسو راوستل، د معکه د بادشاه ورسره زر سړى او د طوب ورسره دولس زره سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7734, '2 Samuel 10:7', '2 Samuel', 10, 7, '&nbsp;داؤد د دې نه خبر شو او يوآب يې د ټول لښکر سره د هغوئ خِلاف ولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7735, '2 Samuel 10:8', '2 Samuel', 10, 8, '&nbsp;عمونيان روان شول او د ربه په دروازه کښې يې د جنګ دپاره صفونه جوړ کړل، کوم چې د هغوئ مرکزى ښار وو، خو هغه نورو يعنې شاميانو او د طوب او معکه سړو په مېدان کښې د جنګ تيارے وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7736, '2 Samuel 10:9', '2 Samuel', 10, 9, '&nbsp;يوآب چې وليدل چې د دشمن لښکر به د مخکښې او شا طرف نه حمله کوى، نو هغۀ ښۀ ښۀ بنى اِسرائيلى فوجيان خوښ کړل او شاميانو ته مخامخ يې په صفونو کښې ودرول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7737, '2 Samuel 10:10', '2 Samuel', 10, 10, '&nbsp;هغۀ پاتې لښکر د خپل ورور ابيشى د مشرۍ لاندې ودرولو، چا چې هغوئ عمونيانو ته مخامخ په صفونو کښې ودرول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7738, '2 Samuel 10:11', '2 Samuel', 10, 11, '&nbsp;يوآب هغۀ ته ووئيل، ”کۀ تا ته پته ولګى چې شاميان ما له شکست راکوى، نو زما مدد له راشه او کۀ عمونيان تا له شکست درکوى، نو زۀ به ستا مدد له درشم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7739, '2 Samuel 10:12', '2 Samuel', 10, 12, '&nbsp;تکړه شه او حوصله مضبوطه کړه. راځئ چې د خپلو خلقو او د خُدائ پاک د ښارونو دپاره سخت جنګ وکړُو. او مالِک خُدائ به هغه څۀ کوى چې د هغۀ په نظر کښې صحيح وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7740, '2 Samuel 10:13', '2 Samuel', 10, 13, '&nbsp;يوآب او د هغۀ سړى د حملې دپاره رامخکښې شول او شاميان وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7741, '2 Samuel 10:14', '2 Samuel', 10, 14, '&nbsp;کله چې عمونيانو وليدل چې شاميان تښتى، نو هغوئ د ابيشى نه وتښتېدل او ښار ته راواپس شول. بيا يوآب د عمونيانو نه راواپس شو او يروشلم ته لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7742, '2 Samuel 10:15', '2 Samuel', 10, 15, '&nbsp;شاميانو ته پته ولګېده چې هغوئ د بنى اِسرائيلو نه شکست خوړلے دے، نو هغوئ خپل ټول لښکر راغونډ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7743, '2 Samuel 10:16', '2 Samuel', 10, 16, '&nbsp;هدد‌عزر بادشاه شاميان راوغوښتل چې هغوئ د فرات سيند نمرخاتۀ طرف ته وُو او هغوئ حلام ته د سوباب د مشرۍ لاندې راغلل. سوباب د ضوباه د هدد‌عزر بادشاه د لښکر مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7744, '2 Samuel 10:17', '2 Samuel', 10, 17, '&nbsp;کله چې داؤد د دې نه خبر شو، نو هغۀ د بنى اِسرائيلو ټول فوجيان راغونډ کړل، د اُردن سيند نه پورې وتل او حلام ته روان شول، هلته شاميانو هغۀ ته مخامخ د جنګ دپاره صفونه جوړ کړى وُو او جنګ شروع شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7745, '2 Samuel 10:18', '2 Samuel', 10, 18, '&nbsp;بنى اِسرائيلو شاميانو له بيا شکست ورکړو. داؤد او د هغۀ سړو اووۀ سوه د جنګى ګاډو والا او څلوېښت زره فوجيان ووژل او هغوئ د دشمن مشر سوباب زخمى کړو، چې بيا د جنګ په مېدان کښې مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7746, '2 Samuel 10:19', '2 Samuel', 10, 19, '&nbsp;چې د هدد‌عزر اختيار لاندې بادشاهانو ته پته ولګېده چې هغوئ د بنى اِسرائيلو نه شکست خوړلے دے، نو هغوئ ورسره صُلح وکړه او د هغوئ ماتحت شول. او شاميان د عمونيانو سره د نورې ملګرتيا کولو نه يرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7747, '2 Samuel 11:1', '2 Samuel', 11, 1, '&nbsp;په سپرلى کښې د کال په کوم وخت چې بادشاهان اکثر جنګ له ځى، داؤد يوآب د هغۀ آفسران او د بنى اِسرائيلو لښکر ولېږلو، هغوئ عمونيانو له شکست ورکړو او د ربه ښار يې محاصره کړو. خو داؤد په خپله په يروشلم کښې ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7748, '2 Samuel 11:2', '2 Samuel', 11, 2, '&nbsp;يوه ورځ په ماښامى کښې داؤد د کټ نه پاڅېدو او د محل چت ته وختو. کله چې هغه هلته ګرځېدلو نو هغۀ يوه ښځه وليده چې لامبل يې. هغه ډېره ښائسته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7749, '2 Samuel 11:3', '2 Samuel', 11, 3, '&nbsp;نو هغۀ يو پېغام وړونکے ولېږلو چې معلومه کړى چې هغه څوک وه، نو هغۀ ته ووئيلے شول چې هغه بت‌‌سبع وه، هغه د الى‌عام لور او د حِتى اورِياه ښځه وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7750, '2 Samuel 11:4', '2 Samuel', 11, 4, '&nbsp;داؤد پېغام وړُونکى ورولېږل چې هغه راولى، هغه ورله راغله او داؤد ورسره څملاستو. هغه د مياشتنۍ بيمارۍ نه ايله صفا شوې وه. بيا هغه واپس کور ته لاړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7751, '2 Samuel 11:5', '2 Samuel', 11, 5, '&nbsp;وروستو هغې ته پته ولګېده چې هغه اُميدواره ده او داؤد له يې پېغام ولېږلو چې خبر شى چې زۀ اُميدواره يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7752, '2 Samuel 11:6', '2 Samuel', 11, 6, '&nbsp;بيا داؤد يوآب له دا پېغام ولېږلو، ”اورِياه حِتے ما له راولېږه.“ يوآب هغه داؤد له ولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
