(7755, '2 Samuel 11:9', '2 Samuel', 11, 9, '&nbsp;خو اورِياه کور ته لا نۀ ړو، هغه د بادشاه د څوکيدارانو سره د محل د دروازې سره څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7756, '2 Samuel 11:10', '2 Samuel', 11, 10, '&nbsp;کله چې داؤد خبر شو چې اورِياه کور ته نۀ دے تلے، نو هغۀ ترې نه تپوس وکړو، ”تۀ د ډېر وخت غېرحاضرۍ نه اوس راواپس شوے يې، تۀ کور ته ولې لا نۀ ړې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7757, '2 Samuel 11:11', '2 Samuel', 11, 11, '&nbsp;اورِياه ورته ووئيل، ”د بنى اِسرائيلو او د يهوداه سړى په جنګ کښې دى او د لوظ صندوق د هغوئ سره دے، زما مشر يوآب او د هغۀ آفسرانو په مېدان کښې خېمې لګولې دى. زۀ څنګه کور ته لاړ شم، يا څنګه خوراک څښاک وکړم او د خپلې ښځې سره څملم؟ زۀ ستا په سر قسم خورم چې زۀ به داسې کار هيڅکله ونۀ کړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7758, '2 Samuel 11:12', '2 Samuel', 11, 12, '&nbsp;نو داؤد وفرمائيل، ”نو دا پاتې ورځ دلته ايسار شه او سبا به زۀ تا واپس ولېږم.“ نو اورِياه په هغه او په ورپسې ورځ په يروشلم کښې ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7759, '2 Samuel 11:13', '2 Samuel', 11, 13, '&nbsp;داؤد هغه د ماښام روټۍ له راوغوښتو او نشه يې کړو. خو اورِياه په هغه شپه بيا کور ته لا نۀ ړو، او د محل د څوکيدارانو په کوټه کښې په کټ کښې څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7760, '2 Samuel 11:14', '2 Samuel', 11, 14, '&nbsp;په ورپسې سحر داؤد يوآب ته يو خط وليکلو او اورِياه په لاس يې ورولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7761, '2 Samuel 11:15', '2 Samuel', 11, 15, '&nbsp;هغۀ وليکل، ”اورِياه په وړومبى صف کښې ودروه، چرته چې جنګ ډېر سخت دے، هغه يواځې پرېږده چې ووژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
