(7769, '2 Samuel 11:23', '2 Samuel', 11, 23, '&nbsp;هغۀ ووئيل، ”زمونږ دشمنان زمونږ نه تکړه وُو او د ښار نه راووتل چې په مېدان کښې مونږ سره جنګ وکړى، خو مونږ هغوئ د ښار دروازې ته واپس وشړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7770, '2 Samuel 11:24', '2 Samuel', 11, 24, '&nbsp;بيا هغوئ د دېوال نه په مونږ باندې غشى راوويشتل او بادشاه سلامت، ستا يو څو آفسران ووژلے شول، ستا آفسر اورِياه حِتے هم ووژلے شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7771, '2 Samuel 11:25', '2 Samuel', 11, 25, '&nbsp;داؤد پېغام وړُونکى ته وفرمائيل، ”د يوآب حوصله افزائى وکړه او ورته ووايه چې خفه نۀ شى، ځکه چې تا ته دا پته نۀ لګى چې څوک به په جنګ کښې مرى. هغۀ ته ووايه چې په ښار باندې يوه مضبوطه حمله وکړى او قبضه يې کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7772, '2 Samuel 11:26', '2 Samuel', 11, 26, '&nbsp;کله چې بت‌‌سبع خبر شوه چې د هغې خاوند وژلے شوے دے، نو هغې ورپسې ماتم وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7773, '2 Samuel 11:27', '2 Samuel', 11, 27, '&nbsp;کله چې د ماتم وخت تېر شو، داؤد هغه راوغوښتله چې محل ته راشى، نو هغه يې ښځه شوه او يو زوئ يې ترې نه پېدا شو. خو چې داؤد کوم عمل کړے وو په هغې باندې مالِک خُدائ نارضا وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7774, '2 Samuel 12:1', '2 Samuel', 12, 1, '&nbsp;مالِک خُدائ ناتن پېغمبر داؤد له ولېږلو. ناتن هغۀ له ورَغلو او دا مثال يې ورته بيان کړو، ”دوه سړى وُو چې په يو ښار کښې اوسېدل، يو مالداره او بل غريب وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7775, '2 Samuel 12:2', '2 Samuel', 12, 2, '&nbsp;مالداره سره ډېر څاروى او ګډې وې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7776, '2 Samuel 12:3', '2 Samuel', 12, 3, '&nbsp;خو د غريب سره صِرف يوه ګډورۍ وه، کومه چې هغۀ اخستې وه. هغۀ د دې خيال ساتلو او هغه د هغۀ په کور کښې د هغۀ د ماشومانو سره لويه شوه. هغې له به يې د خپل خوراک نه خوراک ورکولو او په خپل جام کښې به يې څښلو ته پرېښوده او په خپله غېږه کښې به يې نيوله. ګډورۍ د هغۀ دپاره د لور په شان وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7777, '2 Samuel 12:4', '2 Samuel', 12, 4, '&nbsp;يوه ورځ يو مسافر د هغه مالداره سړى کور ته راغلو. مالداره سړى نۀ غوښتل چې هغه خپل يو ځناور حلال کړى چې د هغۀ دپاره روټۍ تياره کړى، هغۀ د غريب سړى ګډورۍ واخستله او د خپل مېلمه دپاره يې روټۍ تياره کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7778, '2 Samuel 12:5', '2 Samuel', 12, 5, '&nbsp;داؤد هغه مالداره سړى ته سخت غصه شو او ورته يې ووئيل، ”زۀ په ژوندى مالِک خُدائ قسم کوم چې کوم سړى دا کړى وى نو هغه د مرګ لائق دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7779, '2 Samuel 12:6', '2 Samuel', 12, 6, '&nbsp;ځکه چې هغۀ داسې بې‌رحمه کار کړے دے، هغه به خامخا د دې په څلور چنده تاوان ورکوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7780, '2 Samuel 12:7', '2 Samuel', 12, 7, '&nbsp;ناتن داؤد ته وفرمائيل، ”تۀ هغه سړے يې. مالِک خُدائ د بنى اِسرائيلو خُدائ پاک فرمائى، ما تۀ د بنى اِسرائيلو بادشاه جوړ کړې او د ساؤل نه مې بچ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7781, '2 Samuel 12:8', '2 Samuel', 12, 8, '&nbsp;ما تا له د هغۀ بادشاهى او د هغۀ ښځې درکړې دى، ما تۀ په بنى اِسرائيلو او په يهوداه باندې بادشاه جوړ کړې. خو کۀ دا کمه وے نو ما به تا له د دې نه علاوه نور هم درکړے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7782, '2 Samuel 12:9', '2 Samuel', 12, 9, '&nbsp;نو تا د مالِک خُدائ حُکم ته سپک ولې کتلى دى؟ تا دا بد عمل ولې کړے دے؟ تا اورِياه حِتے په جنګ کښې وژلے دے، تا عمونيان پرېښودل چې هغه ووژنى او بيا تا د هغۀ ښځه بوتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7783, '2 Samuel 12:10', '2 Samuel', 12, 10, '&nbsp;نو ستا اولاد به همېشه په جنګ جګړو کښې آخته وى ځکه چې تا زما سپکاوے کړے دے چې د اورِياه ښځه دې بوتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7784, '2 Samuel 12:11', '2 Samuel', 12, 11, '&nbsp;مالِک خُدائ تا ته فرمائى چې زۀ به ستا د خپل خاندان نه څوک د دې سبب وګرځوم چې په تا مصيبت راولى. تۀ به خپلو سترګو ګورې چې زۀ به ستا نه ښځې بوځم او بل سړى له به يې ورکوم، او هغه به په رڼا ورځ ورسره څملى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7785, '2 Samuel 12:12', '2 Samuel', 12, 12, '&nbsp;تا په پټه ګناه کړې ده، خو زۀ به په رڼا ورځ داسې وکړم چې ټول بنى اِسرائيليان يې وګورى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7786, '2 Samuel 12:13', '2 Samuel', 12, 13, '&nbsp;داؤد وفرمائيل، ”ما د مالِک خُدائ خِلاف ګناه کړې ده.“ ناتن ورته وفرمائيل، ”خو مالِک خُدائ تۀ معاف کړے يې، تۀ به نۀ مرې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7787, '2 Samuel 12:14', '2 Samuel', 12, 14, '&nbsp;خو د دې عمل په وجه تا د مالِک خُدائ لوئ سپکاوے کړے دے، نو په دې وجه به ستا ماشوم مړ شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7788, '2 Samuel 12:15', '2 Samuel', 12, 15, '&nbsp;بيا ناتن کور ته لاړو. د حضرت داؤد د زوئ مړ کېدل د اورِياه د ښځې نه چې د داؤد کوم ماشوم پېدا شوے وو مالِک خُدائ هغه سخت بيمار کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7789, '2 Samuel 12:16', '2 Samuel', 12, 16, '&nbsp;داؤد خُدائ پاک ته د دې دپاره سوال وکړو چې ماشوم ښۀ شى. هغۀ روژه ونيوله او هره شپه به د هغۀ کوټې ته تلو او ټوله شپه به يې په زمکه تېروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7790, '2 Samuel 12:17', '2 Samuel', 12, 17, '&nbsp;د هغۀ د دربار آفسران به ورتلل او د هغۀ د پاڅېدو کوشش به يې کولو، خو هغۀ به اِنکار کولو او د هغوئ سره يې هيڅ هم نۀ خوړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7791, '2 Samuel 12:18', '2 Samuel', 12, 18, '&nbsp;يوه هفته وروستو هغه ماشوم مړ شو او د داؤد آفسران يرېدل چې د دې نه يې خبر کړے وے. هغوئ ووئيل، ”کوم وخت چې ماشوم ژوندے وو، نو مونږ به چې د داؤد سره خبرې کولې نو هغۀ به جواب نۀ راکولو. نو هغۀ ته مونږ څنګه ووايو چې د هغۀ ماشوم مړ دے؟ کېدے شى چې هغه خپل ځان ته څۀ نقصان ورسوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7792, '2 Samuel 12:19', '2 Samuel', 12, 19, '&nbsp;کله چې داؤد هغوئ وليدل چې هغوئ د يو بل سره پټې خبرې کولې، نو هغۀ ته پته ولګېده چې ماشوم مړ دے. نو هغۀ ورنه تپوس وکړو، ”ماشوم مړ دے څۀ؟“ نو هغوئ جواب ورکړو، ”آو، مړ دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7793, '2 Samuel 12:20', '2 Samuel', 12, 20, '&nbsp;داؤد د زمکې نه پاڅېدو، وې لامبل، تېل يې ولګول او جامې يې بدلې کړې. بيا هغه لاړو او د مالِک خُدائ په کور کښې يې عبادت وکړو. کله چې هغه محل ته راواپس شو، هغۀ روټۍ راوغوښته. هغوئ روټۍ ورته کېښوده او هغۀ وخوړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7794, '2 Samuel 12:21', '2 Samuel', 12, 21, '&nbsp;نو خپلو آفسرانو داؤد ته ووئيل، ”مونږ په دې پوهه نۀ شُو، کله چې ماشوم ژوندے وو، نو تا به په هغۀ پسې ژړل او خوراک به دې نۀ کولو، خو چې څنګه هغه ماشوم مړ شو، نو تۀ پاڅېدې او خوراک دې شروع کړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7795, '2 Samuel 12:22', '2 Samuel', 12, 22, '&nbsp;داؤد جواب ورکړو، ”آو، کوم وخت چې هغه ژوندے وو نو ما روژه نيولې وه او ژړل مې. زما خيال دا وو چې کېدے شى چې مالِک خُدائ به په ما رحم وکړى او ماشوم به نۀ وژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7796, '2 Samuel 12:23', '2 Samuel', 12, 23, '&nbsp;خو اوس هغه مړ دے، نو زۀ ولې روژه ونيسم؟ زۀ ماشوم بيا ژوندے کولے شم څۀ؟ يوه ورځ به زۀ هم هلته ځم چرته چې هغه دے، خو هغه هيڅکله ما له واپس نۀ شى راتلے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7797, '2 Samuel 12:24', '2 Samuel', 12, 24, '&nbsp;بيا داؤد خپلې ښځې بت‌‌سبع له تسلى ورکړه. د هغې سره څملاستو او د هغې نه يې يو زوئ پېدا شو. داؤد په هغۀ سليمان نوم کېښودو. مالِک خُدائ د ماشوم سره مينه کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7798, '2 Samuel 12:25', '2 Samuel', 12, 25, '&nbsp;او هغۀ ناتن پېغمبر له حُکم ورکړو چې په ماشوم يديدياه نوم کېږدى، ځکه چې مالِک خُدائ د هغۀ سره مينه کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7799, '2 Samuel 12:26', '2 Samuel', 12, 26, '&nbsp;په دې دوران کښې د يوآب جنګ د ربه خِلاف جارى وو، چې د عمون شاهى ښار وو او قبضه کېدو ته نزدې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7800, '2 Samuel 12:27', '2 Samuel', 12, 27, '&nbsp;هغۀ داؤد ته پېغام وړُونکى ولېږل چې ورته ووائى، ”ما په ربه حمله کړې ده او د دې د اوبو مرکز مې قبضه کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');